// Elementra – periodic table data model.
// Source: src/data/elements.data.json, generated by `npm run data` from
// node-periodic-table and periodic-table-data-complete (both MIT licensed).

import raw from './elements.data.json'

type RawElement = {
  z: number
  symbol: string
  name: string
  mass: number
  xpos: number
  ypos: number
  period: number
  phase: string
  melt: number | null
  boil: number | null
  density: number | null
  electronegativity: number | null
  ionization: number | null
  electronAffinity: number | null
  radius: number | null
  shells: number[]
  config: string
  configShort: string
  summary: string | null
  appearance: string | null
  discoveredBy: string | null
  discoveryYear: number | null
  discoveryPlace: string | null
  latinName: string | null
  oxidationStates: string | null
  valence: number | null
  radioactive: boolean
  source: string
}

export type CategoryKey =
  | 'alkali-metal'
  | 'alkaline-earth-metal'
  | 'transition-metal'
  | 'post-transition-metal'
  | 'metalloid'
  | 'reactive-nonmetal'
  | 'halogen'
  | 'noble-gas'
  | 'lanthanide'
  | 'actinide'

export type Phase = 'Solid' | 'Liquid' | 'Gas'
export type MetalType = 'Metal' | 'Nonmetal' | 'Metalloid'

export interface Element {
  atomicNumber: number
  symbol: string
  name: string
  atomicMass: number
  category: string
  categoryKey: CategoryKey
  metalType: MetalType
  group: number | null
  period: number
  block: 's' | 'p' | 'd' | 'f'
  electronConfiguration: string
  electronConfigurationSemantic: string
  state: Phase
  meltingPointK: number | null
  boilingPointK: number | null
  density: number | null
  electronegativity: number | null
  ionizationEnergy: number | null
  electronAffinity: number | null
  atomicRadius: number | null
  shells: number[]
  valenceElectrons: number | null
  oxidationStates: string | null
  radioactive: boolean
  discoveredBy: string | null
  discoveryYear: number | null
  discoveryPlace: string | null
  latinName: string | null
  appearance: string | null
  summary: string
  funFact: string
  xpos: number
  ypos: number
  source: string
}

const METALLOIDS = new Set([5, 14, 32, 33, 51, 52, 84])
const POST_TRANSITION = new Set([13, 31, 49, 50, 81, 82, 83, 113, 114, 115, 116])

function categorize(z: number, xpos: number): CategoryKey {
  if (z >= 57 && z <= 71) return 'lanthanide'
  if (z >= 89 && z <= 103) return 'actinide'
  if (xpos === 1) return z === 1 ? 'reactive-nonmetal' : 'alkali-metal'
  if (xpos === 2) return 'alkaline-earth-metal'
  if (xpos >= 3 && xpos <= 12) return 'transition-metal'
  if (xpos === 17) return 'halogen'
  if (xpos === 18) return 'noble-gas'
  if (METALLOIDS.has(z)) return 'metalloid'
  if (POST_TRANSITION.has(z)) return 'post-transition-metal'
  return 'reactive-nonmetal'
}

function metalTypeOf(key: CategoryKey): MetalType {
  if (key === 'metalloid') return 'Metalloid'
  if (key === 'reactive-nonmetal' || key === 'halogen' || key === 'noble-gas') return 'Nonmetal'
  return 'Metal'
}

function getBlock(z: number, group: number | null): 's' | 'p' | 'd' | 'f' {
  if (group == null) return 'f'
  if (z === 2 || group <= 2) return 's'
  if (group >= 13) return 'p'
  return 'd'
}

// node-periodic-table stores gas densities in g/L and condensed phases in g/cm³.
function normalizeDensity(density: number | null, phase: string): number | null {
  if (density == null) return null
  return phase === 'Gas' ? density / 1000 : density
}

