function makeFunFact(e: RawElement, category: string): string {
  const curated = FUN_FACTS[e.z]
  if (curated) return curated
  if (e.appearance) return `It looks ${e.appearance.replace(/\.$/, '')}.`
  if (e.discoveryYear && e.discoveryYear > 0) {
    return `${e.name} was first identified in ${e.discoveryYear}${e.discoveredBy ? ` by ${e.discoveredBy}` : ''}.`
  }
  return `${e.name} is classed as a ${category.toLowerCase()}.`
}

