export const ELEMENTS: Element[] = (raw as RawElement[]).map(e => {
  const categoryKey = categorize(e.z, e.xpos)
  const group = categoryKey === 'lanthanide' || categoryKey === 'actinide' ? null : e.xpos
  const category = CATEGORY_META[categoryKey].label
  const state: Phase = e.phase === 'Gas' || e.phase === 'Liquid' ? e.phase : 'Solid'

  return {
    atomicNumber: e.z,
    symbol: e.symbol,
    name: e.name,
    atomicMass: e.mass,
    category,
    categoryKey,
    metalType: metalTypeOf(categoryKey),
    group,
    period: e.period,
    block: getBlock(e.z, group),
    electronConfiguration: e.config,
    electronConfigurationSemantic: e.configShort,
    state,
    meltingPointK: e.melt,
    boilingPointK: e.boil,
    density: normalizeDensity(e.density, e.phase),
    electronegativity: e.electronegativity,
    ionizationEnergy: e.ionization,
    electronAffinity: e.electronAffinity,
    atomicRadius: e.radius,
    shells: e.shells,
    valenceElectrons: e.valence,
    oxidationStates: e.oxidationStates,
    radioactive: e.radioactive,
    discoveredBy: e.discoveredBy,
    discoveryYear: e.discoveryYear,
    discoveryPlace: e.discoveryPlace,
    latinName: e.latinName,
    appearance: e.appearance,
    summary: e.summary ?? `${e.name} is element ${e.z} of the periodic table.`,
    funFact: makeFunFact(e, category),
    xpos: e.xpos,
    ypos: e.ypos,
    source: e.source,
  }
})

export const ELEMENT_BY_Z = new Map(ELEMENTS.map(e => [e.atomicNumber, e]))
export const ELEMENT_BY_SYMBOL = new Map(ELEMENTS.map(e => [e.symbol, e]))

export const CATEGORY_COUNTS: Record<CategoryKey, number> = Object.fromEntries(
  CATEGORY_ORDER.map(k => [k, ELEMENTS.filter(e => e.categoryKey === k).length]),
) as Record<CategoryKey, number>

export function formatNumber(n: number | null | undefined, digits = 3): string {
  if (n == null || Number.isNaN(n)) return '—'
  return Number(n.toFixed(digits)).toLocaleString('en-US', { maximumFractionDigits: digits })
}

/* ── Heatmap / property trend helpers ── */
export type PropertyKey =
  | 'electronegativity'
  | 'atomicRadius'
  | 'ionizationEnergy'
  | 'atomicMass'
  | 'meltingPointK'
  | 'boilingPointK'
  | 'density'

type Direction = 'increases' | 'decreases' | 'varies'

