export const PROPERTY_ORDER: PropertyKey[] = [
  'electronegativity', 'atomicRadius', 'ionizationEnergy', 'atomicMass', 'meltingPointK', 'boilingPointK', 'density',
]

const propertyRangeCache = new Map<PropertyKey, { min: number; max: number }>()
const globalAverageCache = new Map<PropertyKey, number>()

export function getPropertyValue(el: Element, key: PropertyKey): number | null {
  return el[key]
}

export function getPropertyRange(key: PropertyKey): { min: number; max: number } {
  const cached = propertyRangeCache.get(key)
  if (cached) return cached

  const vals = ELEMENTS.map(e => getPropertyValue(e, key)).filter((v): v is number => v != null && !Number.isNaN(v))
  const range = vals.length > 0 ? { min: Math.min(...vals), max: Math.max(...vals) } : { min: 0, max: 1 }

  propertyRangeCache.set(key, range)
  return range
}

/** The elements with the highest and lowest value for a property. */
export function getPropertyExtremes(key: PropertyKey): { high: Element; low: Element } {
  const withData = ELEMENTS.filter(e => getPropertyValue(e, key) != null)
  const sorted = [...withData].sort((a, b) => (getPropertyValue(b, key) ?? 0) - (getPropertyValue(a, key) ?? 0))
  return { high: sorted[0], low: sorted[sorted.length - 1] }
}

const HEAT_STOPS: [number, number, number][] = [
  [37, 52, 148],   // indigo
  [33, 113, 181],  // blue
  [34, 168, 160],  // teal
  [120, 198, 90],  // green
  [240, 200, 60],  // yellow
  [244, 120, 60],  // orange
]

function heatRgb(t: number): [number, number, number] {
  const clamped = Math.max(0, Math.min(1, t))
  const seg = clamped * (HEAT_STOPS.length - 1)
  const i = Math.floor(seg)
  const f = seg - i
  const a = HEAT_STOPS[i]
  const b = HEAT_STOPS[Math.min(HEAT_STOPS.length - 1, i + 1)]
  return [0, 1, 2].map(k => Math.round(a[k] + (b[k] - a[k]) * f)) as [number, number, number]
}

/** A heatmap colour (cool → warm) for a normalized 0..1 value. */
export function heatColor(t: number): string {
  const [r, g, b] = heatRgb(t)
  return `rgb(${r}, ${g}, ${b})`
}

/** Whether dark text reads better than white text on the heat colour for t. */
export function heatNeedsDarkText(t: number): boolean {
  const [r, g, b] = heatRgb(t).map(c => {
    const s = c / 255
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 0.3
}

/** Position of a value on the heat scale, log-scaled for very skewed properties. */
export function heatPosition(el: Element, key: PropertyKey): number | null {
  const v = getPropertyValue(el, key)
  if (v == null) return null
  return normalizedProperty(el, key)
}

/** State of an element at a given temperature (K), at roughly 1 atm. */
export function stateAtTemperature(el: Element, tempK: number): Phase | 'Unknown' {
  const mp = el.meltingPointK
  const bp = el.boilingPointK
  if (mp == null && bp == null) return 'Unknown'
  if (mp != null && tempK < mp) return 'Solid'
  if (bp != null && tempK >= bp) return 'Gas'
  // Between the two points it is liquid; with only one point known we cannot say.
  return mp != null && bp != null ? 'Liquid' : 'Unknown'
}

/* ── Radar / fingerprint helpers ── */
export const RADAR_AXES: PropertyKey[] = [
  'atomicMass', 'electronegativity', 'ionizationEnergy', 'atomicRadius', 'density', 'meltingPointK',
]

const LOG_SCALED = new Set<PropertyKey>(['density', 'meltingPointK', 'boilingPointK', 'ionizationEnergy'])

export function isLogScaled(key: PropertyKey): boolean {
  return LOG_SCALED.has(key)
}

/** A 0..1 range-normalized value for an element's property (log scaled for skewed data). */
export function normalizedProperty(el: Element, key: PropertyKey): number {
  const v = getPropertyValue(el, key)
  if (v == null || Number.isNaN(v)) return 0
  const { min, max } = getPropertyRange(key)
  if (max === min) return 0.5
  if (LOG_SCALED.has(key)) {
    const lv = Math.log10(Math.max(v, 0.0001))
    const lmin = Math.log10(Math.max(min, 0.0001))
    const lmax = Math.log10(Math.max(max, 0.0001))
    return (lv - lmin) / (lmax - lmin || 1)
  }
  return (v - min) / (max - min)
}

/** Average normalized value across the elements that have data for the property. */
export function globalAverageNormalized(key: PropertyKey): number {
  const cached = globalAverageCache.get(key)
  if (cached != null) return cached

  const vals = ELEMENTS.filter(e => getPropertyValue(e, key) != null).map(e => normalizedProperty(e, key))
  const average = vals.length > 0 ? vals.reduce((a, b) => a + b, 0) / vals.length : 0

  globalAverageCache.set(key, average)
  return average
}

export interface RadarPoint { key: PropertyKey; label: string; short: string; value: number; avg: number; raw: number | null }

export function getRadarData(el: Element): RadarPoint[] {
  return RADAR_AXES.map(key => ({
    key,
    label: PROPERTY_META[key].label,
    short: PROPERTY_META[key].short,
    value: normalizedProperty(el, key),
    avg: globalAverageNormalized(key),
    raw: getPropertyValue(el, key),
  }))
}

/** Deterministic "element of the day" so it works offline and matches for everyone. */
export function elementOfTheDay(date = new Date()): Element {
  const day = Math.floor(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / 86_400_000)
  // Multiply by a prime that is coprime with 118 so consecutive days jump around the table.
  return ELEMENTS[(day * 37) % ELEMENTS.length]
}
